#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: variáveis de produção do projeto Vercel `replica` (web/), lidas por web/src (process.env.*).
# Nada vai para .env nem para argv: senhas e chaves passam por stdin (vercel env add, psql, curl -H @-).
# Libera login de web_reader/web_writer com senha nova (gravada como verificador SCRAM, nunca em texto no log
# do Postgres), monta as URLs do Transaction pooler, confere cada chave na fonte e grava só em Production.
# Uso: etl/deploy/vercel-env-setup.sh   (rode do Mac, com `vercel login` e `gh auth login` feitos)
# Rodar de novo troca as senhas do banco: o deploy no ar perde a conexão até o próximo deploy.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8
export GH_REPO="${GH_REPO:-AlexandreCamerini/replica}"
VERCEL_PROJECT="${VERCEL_PROJECT:-replica}"
ENV_FILE="/nonexistent/.env"   # sem valor sugerido de .env e sem gravar nele (write_env não é usado)
LINK="$(mktemp -d "${TMPDIR:-/tmp}/vercel-link.XXXXXX")"
trap 'rm -rf "$LINK"' EXIT
VERCEL_SET=()

# url_env URL: decompõe a URL (lida da env, nunca de argv) em linhas PG*=valor.
url_env() {
  PG_URL="$1" python3 - <<'PYEOF'
import os
from urllib.parse import urlsplit, unquote, parse_qs
u = urlsplit(os.environ["PG_URL"])
q = {k: v[-1] for k, v in parse_qs(u.query).items()}
env = {"PGHOST": u.hostname or "", "PGPORT": str(u.port or 5432), "PGUSER": unquote(u.username or ""),
       "PGPASSWORD": unquote(u.password or ""), "PGDATABASE": unquote(u.path.lstrip("/")) or "postgres",
       "PGSSLMODE": q.get("sslmode", "require"), "PGCONNECT_TIMEOUT": "15", "PGAPPNAME": "vercel-env-setup"}
assert all("\n" not in v for v in env.values())
print("\n".join(f"{k}={v}" for k, v in env.items()))
PYEOF
}
# upsql URL ARGS: psql com as PG* só no subshell (export é builtin: nada em argv).
upsql() {
  local env; env=$(url_env "$1") || return 1; shift
  ( while IFS= read -r kv; do export "$kv"; done <<<"$env"; exec psql -X -q -At -v ON_ERROR_STOP=1 "$@" )
}
# scram SENHA (env): verificador SCRAM-SHA-256 no formato do Postgres; a senha em texto não chega ao banco.
scram() {
  PW="$1" python3 - <<'PYEOF'
import os, hashlib, hmac, base64
pw, salt, it = os.environ["PW"].encode(), os.urandom(16), 4096
salted = hashlib.pbkdf2_hmac("sha256", pw, salt, it)
ck = hmac.new(salted, b"Client Key", "sha256").digest()
sk = hmac.new(salted, b"Server Key", "sha256").digest()
b = lambda x: base64.b64encode(x).decode()
print(f"SCRAM-SHA-256${it}:{b(salt)}${b(hashlib.sha256(ck).digest())}:{b(sk)}")
PYEOF
}
vc() { ( cd "$LINK" && vercel "$@" ); }
# vercel_set NOME VALOR plain|sensitive: substitui em Production; valor por stdin.
vercel_set() {
  local flag=(); [[ "$3" == sensitive ]] && flag=(--sensitive)
  vc env rm "$1" production --yes >/dev/null 2>&1 || true
  if printf '%s' "$2" | vc env add "$1" production "${flag[@]}" >/dev/null 2>&1; then
    VERCEL_SET+=("$1"); printf '  %s✓ set%s Vercel %s (%s)\n' "$GREEN" "$RESET" "$1" "$3"
  else
    SKIPPED+=("Vercel $1 (Settings → Environment Variables)"); warn "não gravei $1 na Vercel"
  fi
}
# auth_probe URL CHAVE: 200 se a chave vale no Supabase Auth. Chave por stdin (-H @-).
auth_probe() { printf 'apikey: %s\n' "$2" | curl -s -o /dev/null -w '%{http_code}' -H @- "$1/auth/v1/settings" || true; }

banner "Variáveis de produção na Vercel"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pré-requisitos"
for c in vercel psql python3 openssl curl gh; do
  command -v "$c" >/dev/null || { warn "falta $c (vercel: npm i -g vercel; psql: brew install postgresql@16)"; exit 1; }
done
WHO=$(vercel whoami 2>/dev/null) || { warn "vercel sem login: rode vercel login e repita"; exit 1; }
say "Vercel: $WHO · projeto $VERCEL_PROJECT"
( cd "$LINK" && vercel link --yes --project "$VERCEL_PROJECT" >/dev/null 2>&1 ) \
  || { warn "não achei o projeto $VERCEL_PROJECT na conta $WHO"; exit 1; }
gh auth status >/dev/null 2>&1 || warn "gh sem login: o passo do GitHub vai ficar para depois"
note "Tudo é gravado só em Production. Preview fica sem banco de propósito: apontaria para os dados reais."
pause "Enter para seguir"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Banco de produção: conexão de administrador"
say "Usada só aqui, para liberar o login dos usuários do app. Não é gravada em lugar nenhum."
open_url "https://supabase.com/dashboard/projects"
step "Projeto de produção → botão Connect (topo) → Connection String → 'Session pooler' (porta 5432)."
step "Copie a URI como está (usuário postgres.<ref>, com [YOUR-PASSWORD]); a senha é pedida em seguida."
note "Senha do banco = a definida ao criar o projeto. Esqueceu: Project Settings → Database → Reset database password."
while :; do
  ask_secret ADMIN_URL "Cole a URI como o Supabase mostra, com [YOUR-PASSWORD] (entrada oculta):"
  if [[ ! "$ADMIN_URL" =~ ^postgres(ql)?:// ]]; then warn "não começa com postgres:// ou postgresql://"; continue; fi
  if [[ "$ADMIN_URL" == *"[YOUR-PASSWORD]"* ]]; then
    ask_secret DB_PASS "Senha do banco (entrada oculta; caracteres especiais são codificados aqui):"
    ADMIN_URL=$(U="$ADMIN_URL" P="$DB_PASS" python3 -c 'import os, urllib.parse as u; print(os.environ["U"].replace("[YOUR-PASSWORD]", u.quote(os.environ["P"], safe="")))')
  else
    # senha colada crua (com # / ? @): codifica tudo entre o primeiro ":" do usuário e o último "@"
    ADMIN_URL=$(U="$ADMIN_URL" python3 -c 'import os, re, urllib.parse as u
s = os.environ["U"]; m = re.match(r"^(postgres(?:ql)?://[^:/@]+):(.*)@([^@]+)$", s)
print(f"{m[1]}:{u.quote(u.unquote(m[2]), safe=str())}@{m[3]}" if m else s)')
  fi
  ENVL=$(url_env "$ADMIN_URL") || { warn "URI ilegível (senha com / ? # precisa de %-encoding)"; continue; }
  HOST=$(sed -n 's/^PGHOST=//p' <<<"$ENVL"); USER_=$(sed -n 's/^PGUSER=//p' <<<"$ENVL")
  if [[ "$HOST" != *.pooler.supabase.com || "$USER_" != postgres.* ]]; then warn "não é o pooler do Supabase (host *.pooler.supabase.com, usuário postgres.<ref>)"; continue; fi
  REF="${USER_#postgres.}"
  if ROLES=$(upsql "$ADMIN_URL" -c "select string_agg(rolname, ' ' order by rolname) from pg_roles where rolname in ('web_reader','web_writer')" 2>&1); then break; fi
  warn "não conectou: $(printf '%s' "${ROLES//"$ADMIN_URL"/<url>}" | tail -n 1)"
  confirm "Tentar outra URI?" || exit 1
done
[[ "$ROLES" == "web_reader web_writer" ]] || { warn "web_reader/web_writer não existem: aplique as migrações (db/migrate.sh) antes"; exit 1; }
PEOPLE=$(upsql "$ADMIN_URL" -c "select count(*) from people" 2>/dev/null || echo "?")
REGION=$(sed -E 's/^aws-[0-9]+-([a-z0-9-]+)\.pooler\.supabase\.com$/\1/' <<<"$HOST")
say "Projeto $REF · região $REGION · $PEOPLE pessoas carregadas"
case "$REGION" in   # funções da Vercel na região do banco: cada consulta paga a distância
  sa-east-1) FN_REGION=gru1 ;; us-east-1) FN_REGION=iad1 ;; us-east-2) FN_REGION=cle1 ;; us-west-1) FN_REGION=sfo1 ;;
  us-west-2) FN_REGION=pdx1 ;; eu-central-1) FN_REGION=fra1 ;; eu-west-1) FN_REGION=dub1 ;; eu-west-2) FN_REGION=lhr1 ;; *) FN_REGION="" ;;
esac
[[ -n "$FN_REGION" ]] && note "Região das funções na Vercel deve ser $FN_REGION (Settings → Functions → Function Region)."
[[ "$PEOPLE" =~ ^[1-9] ]] || warn "people vazia: o site sobe sem dados até rodar etl/deploy/prod-restore.sh"
pause "Enter para seguir"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Usuários do app: web_reader e web_writer"
say "O app lê como web_reader (só select, RLS) e escreve como web_writer (conta, acompanhar, sugestões)."
say "Vou gerar uma senha nova para cada um e liberar o login deles em PRODUÇÃO."
note "O banco recebe só o verificador SCRAM; a senha em texto vai direto para a Vercel."
confirm "Definir senha nova e liberar login de web_reader e web_writer?" || exit 1
READER_PW=$(openssl rand -hex 24); WRITER_PW=$(openssl rand -hex 24)
printf "alter role web_reader login password '%s';\nalter role web_writer login password '%s';\n" \
  "$(scram "$READER_PW")" "$(scram "$WRITER_PW")" | upsql "$ADMIN_URL" -f - \
  || { warn "alter role falhou (precisa ser o usuário postgres)"; exit 1; }
DATABASE_URL="postgresql://web_reader.$REF:$READER_PW@$HOST:6543/postgres?sslmode=require"
DATABASE_WRITE_URL="postgresql://web_writer.$REF:$WRITER_PW@$HOST:6543/postgres?sslmode=require"
say "Testando as duas pelo Transaction pooler (porta 6543), como o app vai conectar..."
for i in 1 2 3 4 5 6; do   # o pooler leva alguns segundos para ver a senha nova
  R=$(upsql "$DATABASE_URL" -c "select count(*) from people" 2>/dev/null) && W=$(upsql "$DATABASE_WRITE_URL" -c "select 1" 2>/dev/null) && break
  R=""; sleep 5
done
[[ -n "$R" ]] || { warn "o pooler não aceitou os usuários novos; rode de novo em um minuto"; exit 1; }
say "web_reader lê $R pessoas; web_writer conecta."
pause "Enter para seguir"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase Auth: URL e chaves"
NEXT_PUBLIC_SUPABASE_URL="https://$REF.supabase.co"
open_url "https://supabase.com/dashboard/project/$REF/settings/api-keys"
step "Aba 'Legacy API keys' (ou as novas publishable/secret, servem igual)."
say "URL do projeto: $NEXT_PUBLIC_SUPABASE_URL"
while :; do
  ask NEXT_PUBLIC_SUPABASE_ANON_KEY "Cole a chave anon (pública):"
  [[ "$(auth_probe "$NEXT_PUBLIC_SUPABASE_URL" "$NEXT_PUBLIC_SUPABASE_ANON_KEY")" == 200 ]] && break
  warn "o Supabase recusou essa chave"
done
while :; do
  ask_secret SUPABASE_SERVICE_ROLE_KEY "Cole a chave service_role (entrada oculta):"
  if [[ "$SUPABASE_SERVICE_ROLE_KEY" == "$NEXT_PUBLIC_SUPABASE_ANON_KEY" ]]; then warn "é a anon de novo; copie a service_role"; continue; fi
  [[ "$(auth_probe "$NEXT_PUBLIC_SUPABASE_URL" "$SUPABASE_SERVICE_ROLE_KEY")" == 200 ]] && break
  warn "o Supabase recusou essa chave"
done
pause "As duas valem. Enter para seguir"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Turnstile (CAPTCHA)"
open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
step "Add widget → nome 'replica' → modo Managed."
step "Hostnames: o domínio final e vercel.app (vale para a URL de produção do projeto)."
step "Crie e copie a Site Key e a Secret Key."
ask NEXT_PUBLIC_TURNSTILE_SITE_KEY "Cole a Site Key:"
while :; do
  ask_secret TURNSTILE_SECRET_KEY "Cole a Secret Key (entrada oculta):"
  # token falso: secret válida responde invalid-input-response; inválida, invalid-input-secret
  TS=$(printf 'secret=%s&response=probe' "$TURNSTILE_SECRET_KEY" | curl -s --data @- https://challenges.cloudflare.com/turnstile/v0/siteverify || true)
  [[ "$TS" == *invalid-input-secret* || -z "$TS" ]] || break
  warn "a Cloudflare recusou essa Secret Key"
done
open_url "https://supabase.com/dashboard/project/$REF/auth/protection"
step "No Supabase: Attack Protection → ligue 'Enable Captcha protection' → provedor Turnstile."
step "Cole a MESMA Secret Key e salve. Sem isso o login por código não confere o CAPTCHA."
pause "Enter quando tiver salvo no Supabase"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Segredos do app e endereço público"
SESSION_SECRET=$(openssl rand -base64 48 | tr -d '\n'); REVALIDATE_SECRET=$(openssl rand -base64 48 | tr -d '\n')
say "Gerei SESSION_SECRET e REVALIDATE_SECRET novos (nunca os de dev)."
say "SITE_URL é o endereço público, usado no og:image (WhatsApp) e no /api/revalidate do ETL."
note "Sem domínio ainda: Enter deixa sem; rode de novo depois do primeiro deploy."
while :; do
  ask SITE_URL "SITE_URL (ex.: https://replica.vercel.app):"
  [[ -z "$SITE_URL" || "$SITE_URL" =~ ^https://[^/]+$ ]] && break
  warn "use https://host, sem barra no fim"
done
pause "Enter para seguir"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Gravar na Vercel (Production)"
say "Projeto $VERCEL_PROJECT, ambiente Production. Cada variável é substituída se já existir."
note "Sensitive: DATABASE_URL, DATABASE_WRITE_URL, SUPABASE_SERVICE_ROLE_KEY, TURNSTILE_SECRET_KEY, SESSION_SECRET, REVALIDATE_SECRET"
note "Plain: NEXT_PUBLIC_SUPABASE_URL, NEXT_PUBLIC_SUPABASE_ANON_KEY, NEXT_PUBLIC_TURNSTILE_SITE_KEY${SITE_URL:+, SITE_URL}"
confirm "Gravar agora?" || exit 1
vercel_set DATABASE_URL "$DATABASE_URL" sensitive
vercel_set DATABASE_WRITE_URL "$DATABASE_WRITE_URL" sensitive
vercel_set SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY" sensitive
vercel_set TURNSTILE_SECRET_KEY "$TURNSTILE_SECRET_KEY" sensitive
vercel_set SESSION_SECRET "$SESSION_SECRET" sensitive
vercel_set REVALIDATE_SECRET "$REVALIDATE_SECRET" sensitive
vercel_set NEXT_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL" plain
vercel_set NEXT_PUBLIC_SUPABASE_ANON_KEY "$NEXT_PUBLIC_SUPABASE_ANON_KEY" plain
vercel_set NEXT_PUBLIC_TURNSTILE_SITE_KEY "$NEXT_PUBLIC_TURNSTILE_SITE_KEY" plain
[[ -n "$SITE_URL" ]] && vercel_set SITE_URL "$SITE_URL" plain
pause "Enter para seguir"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "ETL avisa o site e conferência"
say "Depois de cada carga o ETL chama \$REVALIDATE_URL com o mesmo REVALIDATE_SECRET (.github/workflows/etl.yml)."
set_secret REVALIDATE_SECRET "$REVALIDATE_SECRET"
if [[ -n "$SITE_URL" ]]; then set_var REVALIDATE_URL "$SITE_URL/api/revalidate"
else SKIPPED+=("GitHub variable REVALIDATE_URL (rode de novo com SITE_URL)"); fi
say "Conferindo o que ficou em Production na Vercel..."
LS=$(vc env ls production 2>/dev/null || true)
MISSING=()
for v in DATA_SOURCE AUTH_PROVIDER PG_POOL_MAX PG_WRITE_POOL_MAX DATABASE_URL DATABASE_WRITE_URL \
         NEXT_PUBLIC_SUPABASE_URL NEXT_PUBLIC_SUPABASE_ANON_KEY SUPABASE_SERVICE_ROLE_KEY \
         NEXT_PUBLIC_TURNSTILE_SITE_KEY TURNSTILE_SECRET_KEY SESSION_SECRET REVALIDATE_SECRET; do
  grep -qw "$v" <<<"$LS" || MISSING+=("$v")
done
if (( ${#MISSING[@]} )); then warn "faltam na Vercel: ${MISSING[*]}"; SKIPPED+=("Vercel: ${MISSING[*]}")
else say "As 13 variáveis obrigatórias estão em Production."; fi
note "Próximo passo: Deployments → Redeploy (ou um push na main). Variável nova só vale em deploy novo."
pause "Enter para o resumo"

finish
